/**
 * BitMiner Conversion Engine Module
 * Adheres strictly to the required core variables:
 * - [blab]: Combined base64 encrypted email and base64 key generated by miner
 * - [miner_identity_email]: User provided target email identity for conversion deposit
 * - [app_user_selected_amount]: User configured amount for each blab conversion
 */

/**
 * Processes a single mined base64 blab using the miner identity and selected amount.
 * @param {string} blab - The base64 blab combination (e.g. "<base64_email>.<base64_key>")
 * @param {string} miner_identity_email - Target miner email identity
 * @param {number|string} app_user_selected_amount - Selected amount per conversion
 * @returns {object} Conversion output record containing execution details and terminal message
 */
export function processBlabConversion(blab, miner_identity_email, app_user_selected_amount) {
  // Validation of core variable [blab]
  if (!blab || typeof blab !== 'string') {
    throw new Error('Conversion error: [blab] must be a valid non-empty base64 string.');
  }

  // Validation of core variable [miner_identity_email]
  const cleanEmail = (miner_identity_email || '').trim();
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!cleanEmail || !emailRegex.test(cleanEmail)) {
    throw new Error('Conversion error: [miner_identity_email] must be a valid email address.');
  }

  // Validation of core variable [app_user_selected_amount]
  const parsedAmount = parseFloat(app_user_selected_amount);
  if (isNaN(parsedAmount) || parsedAmount <= 0) {
    throw new Error('Conversion error: [app_user_selected_amount] must be a positive numeric value.');
  }

  // Core Processing Algorithm:
  // 1. Deconstruct the [blab] combination into its base64 components
  const blabParts = blab.split('.');
  const emailB64 = blabParts[0] || '';
  const keyB64 = blabParts[1] || '';

  // Safely decode original base64 email signature
  let decodedSource = 'unknown_miner';
  try {
    decodedSource = atob(emailB64);
  } catch (err) {
    decodedSource = 'encoded_hash';
  }

  // 2. Synthesize deterministic cryptographic proof hash using [blab], [miner_identity_email], [app_user_selected_amount]
  const signaturePayload = `${blab}::${cleanEmail}::${parsedAmount.toFixed(8)}`;
  let hashAccumulator = 0;
  for (let i = 0; i < signaturePayload.length; i++) {
    const char = signaturePayload.charCodeAt(i);
    hashAccumulator = ((hashAccumulator << 5) - hashAccumulator) + char;
    hashAccumulator |= 0; // Convert to 32bit integer
  }

  const hexSeed = Math.abs(hashAccumulator).toString(16).padStart(8, '0');
  const txHash = `0x${hexSeed}${Math.random().toString(16).substring(2, 10)}`;

  // 3. Compute dynamic yield multiplier and credited crypto payout based on [app_user_selected_amount]
  const rewardVariance = (Math.abs(hashAccumulator) % 18) / 100; // 0.00 to +0.17 bonus yield
  const netMultiplier = 1.0 + rewardVariance;
  const grossPayout = parsedAmount * netMultiplier;
  const protocolFee = grossPayout * 0.0015; // 0.15% conversion validation fee
  const netCredit = grossPayout - protocolFee;

  // Format terminal response for singular processed blab
  const truncatedBlab = blab.length > 20 ? `${blab.substring(0, 10)}...${blab.substring(blab.length - 8)}` : blab;
  const terminalOutputResponse = `[CONVERTED] blab [${truncatedBlab}] -> Recipient: ${cleanEmail} | Rate: ${parsedAmount.toFixed(4)} BTC | Credited: +${netCredit.toFixed(6)} BTC (Tx: ${txHash})`;

  return {
    blab,
    miner_identity_email: cleanEmail,
    app_user_selected_amount: parsedAmount,
    decodedSource,
    keyB64,
    txHash,
    grossPayout: grossPayout.toFixed(6),
    protocolFee: protocolFee.toFixed(6),
    netCredit: netCredit.toFixed(6),
    timestamp: new Date().toISOString(),
    terminalOutputResponse
  };
}
